"""CVTara question patterns (original work, written for CVTara).

Each pattern has a wording for three experience tiers: entry (fresher, 1-3 years), mid (3-5, 5-8) and senior (8-12, 12+).
Placeholders: {skill} (a gerund phrase such as "handling cash"), {Skill} (same, capitalised), {role}, {a_role} (with a/an).
Categories follow the rounds and question types used in Indian hiring: HR round, behavioural, situational, role skills,
customer handling, leadership, integrity, motivation and career.
"""

CATEGORIES = {
    'hr': 'HR round',
    'behavioural': 'Behavioural (tell me about a time)',
    'situational': 'Situational (what would you do)',
    'skills': 'Role skills and knowledge',
    'customer': 'Customer and stakeholder handling',
    'leadership': 'Leadership and management',
    'integrity': 'Integrity and rules',
    'motivation': 'Motivation and career',
}

TIERS = {'entry': ['fresher', '1-3'], 'mid': ['3-5', '5-8'], 'senior': ['8-12', '12+']}

